> For this kind of changes that impact performance, please provide a comparison of the two methods to prove this version is worth implementing instead of the existing one
```
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Title</title>
</head>
<body>
<div id="app"></div>
<script>
    let callbacks = [];
    let time = 0;
    function flushCallbacks() {
        const copies = callbacks.slice(0);
        callbacks.length = 0;
        for (let i = 0; i < copies.length; i++) {
            copies[i]();
        }
    }

    let t0, t1;

    for (let i = 0; i < 100000; i++) {
        if (i === 0) {
            t0 = performance.now();
        }
        callbacks.push(() => time++);
        if (i % 10000 === 0) {
            flushCallbacks();
        }
        if (i === 99999) {
            t1 = performance.now();
            console.log(t1 - t0, "old flush");
        }
    }

    callbacks = [];

    function flushCallbacks1() {
        const currentLength = callbacks.length;
        const currentCallback = callbacks.splice(0);
        for (let i = 0; i < currentLength; i++) {
            currentCallback[i]();
        }
    }

    for (let i = 0; i < 100000; i++) {
        if (i === 0) {
            t0 = performance.now();
        }
        callbacks.push(() => time++);
        if (i % 10000 === 0) {
            flushCallbacks1();
        }
        if (i === 99999) {
            t1 = performance.now();
            console.log(t1 - t0, "new flush");
        }
    }

</script>
</body>
</html>
```
